const lessonSteps = (kit) => {
  if (!kit.lessonFlow) {
    return kit.classroomIntegration
      .split(/(?<=\.)\s+/)
      .slice(0, 5)
      .map((step) => step.replace(/^\d+(?:th|st|nd|rd) grade:\s*/i, "").trim())
      .filter(Boolean);
  }

  return kit.lessonFlow
    .split(/(?=\d+\.\s)/)
    .map((step) => step.replace(/^\d+\.\s*/, "").trim())
    .filter(Boolean);
};

